import * as vscode from 'vscode';

export interface EclConfig {
  /** Log message prefix marker, also used to identify logs generated by this extension */
  prefix: string;
  /** Quote style used for the log message */
  quote: string;
  /** Whether to append a semicolon at the end */
  semicolon: boolean;
  /** Log function used for generated statements, e.g. console.log */
  logFunction: string;
  /** Whether the message includes the file name */
  includeFilename: boolean;
  /** Whether the message includes the line number */
  includeLineNumber: boolean;
  /** Message template; placeholders: ${prefix} ${file} ${line} ${func} ${cls} ${expr} */
  messageTemplate: string;
  /** Whether to show diagnostic markers on console.* lines */
  diagnosticsEnabled: boolean;
  /** Severity of the diagnostics */
  diagnosticsSeverity: 'error' | 'warning' | 'information' | 'hint';
  /** Whether to refresh file names / line numbers in generated logs on save */
  updateLineNumbersOnSave: boolean;
  /** Directory names excluded from workspace scanning */
  workspaceExcludeDirs: string[];
}

export function getConfig(scope?: vscode.ConfigurationScope): EclConfig {
  const cfg = vscode.workspace.getConfiguration('easyConsoleLog', scope);
  return {
    prefix: cfg.get<string>('logMessagePrefix') ?? '🪵',
    quote: cfg.get<string>('quote') ?? "'",
    semicolon: cfg.get<boolean>('addSemicolon') ?? true,
    logFunction: cfg.get<string>('logFunction') ?? 'console.log',
    includeFilename: cfg.get<boolean>('includeFilename') ?? true,
    includeLineNumber: cfg.get<boolean>('includeLineNumber') ?? true,
    messageTemplate:
      cfg.get<string>('messageTemplate') ?? '${prefix} ~ ${location} ~ ${expr}:',
    diagnosticsEnabled: cfg.get<boolean>('diagnostics.enabled') ?? true,
    diagnosticsSeverity:
      cfg.get<'error' | 'warning' | 'information' | 'hint'>(
        'diagnostics.severity'
      ) ?? 'hint',
    updateLineNumbersOnSave: cfg.get<boolean>('updateLineNumbersOnSave') ?? false,
    workspaceExcludeDirs: cfg.get<string[]>('workspace.excludeDirs') ?? [],
  };
}
